cd "$(mktemp -d)" && export STATE_DIR="$PWD/state" && B=<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g3-3/bot.mjs && cat > check.mjs <<EOF
import assert from 'node:assert/strict';
import { recordUnsubscribe as unsub, recordResubscribe as resub, mayEmail, normalizeEmail } from '$B';
const M = (to, kind='marketing') => ({ to, kind });
const d = (s) => new Date(s);
const now = d('2026-10-22T12:00:00Z');

// fresh address: marketing allowed, unknown address not blocked
assert.deepEqual(await mayEmail(M('new@example.com'), now), { allowed: true, reason: null });

// unsubscribe, then transactional still allowed, marketing blocked
await unsub('Ann <Ann.Lee+shop@Example.com>', d('2026-10-01T00:00:00Z'));
assert.deepEqual(await mayEmail(M('ann.lee@example.com'), now), { allowed: false, reason: 'unsubscribed' });
assert.deepEqual(await mayEmail(M('ANN@example.com', 'transactional'), now), { allowed: true, reason: null });

// redelivery of same event is idempotent
await unsub('ann.lee@example.com', d('2026-10-01T00:00:00Z'));

// late resubscribe OLDER than the unsubscribe does not re-enable
await resub('ann.lee@example.com', d('2026-09-30T00:00:00Z'));
assert.equal((await mayEmail(M('ann.lee@example.com'), now)).allowed, false);

// newer explicit resubscribe re-enables marketing
await resub('ann.lee@example.com', d('2026-10-10T00:00:00Z'));
assert.equal((await mayEmail(M('ann.lee@example.com'), now)).allowed, true);

// late unsubscribe OLDER than the resubscribe does not block
await unsub('ann.lee@example.com', d('2026-10-05T00:00:00Z'));
assert.equal((await mayEmail(M('ann.lee@example.com'), now)).allowed, true);

// googlemail alias maps to the same person
await unsub('<EMAIL>', d('2026-10-20T00:00:00Z'));
assert.equal((await mayEmail(M('<EMAIL>'), now)).reason, 'unsubscribed');

// invalid input
assert.equal((await mayEmail(M('not-an-email'), now)).reason, 'invalid_address');
assert.equal((await mayEmail(M('<EMAIL>', 'digest'), now)).reason, 'unknown_kind');
await assert.rejects(unsub('nope', d('2026-10-01T00:00:00Z')), TypeError);
await assert.rejects(unsub('<EMAIL>', 'yesterday'), TypeError);

// tie: unsubscribe wins over resubscribe at the same instant
const t = d('2026-10-15T00:00:00Z');
await resub('tie@example.com', t); await unsub('tie@example.com', t);
assert.equal((await mayEmail(M('tie@example.com'), now)).allowed, false);

// concurrent workers, separate processes, same address
const { execFileSync } = await import('node:child_process');
const cmd = "import('$B').then(m=>m.recordUnsubscribe('race@example.com', new Date(Date.UTC(2026,9,21,0,0,process.argv[1]))))";
await Promise.all([...Array(8).keys()].map(i => new Promise((res, rej) =>
  require_spawn(i, res, rej))));
function require_spawn(i, res, rej) {
  import('node:child_process').then(({ execFile }) =>
    execFile(process.execPath, ['-e', cmd, String(i)], { env: process.env }, (e) => e ? rej(e) : res()));
}
await new Promise(r => setTimeout(r, 1500));
assert.equal((await mayEmail(M('race@example.com'), now)).reason, 'unsubscribed');

console.log('normalize:', normalizeEmail('  "A" <<EMAIL>> '));
console.log('ALL CHECKS PASSED');
EOF
node check.mjs; echo "exit=$?"; echo "events on disk for race@: $(find "$STATE_DIR" -name '*.json' | wc -l | tr -d ' ') total json files"; rm -rf "$PWD"
